        _q("Which word describes a character's personality?", ["trait", "setting", "title"], 0, "Traits describe how a character acts."),
        _q("The mood of a setting is...", ["the feeling it creates", "its size", "its name"], 0, "Mood is the feeling."),
        _q("What does a character's want create?", ["The story's problem", "The title", "The setting"], 0, "The want leads to the problem."),
        _q("A good solution should...", ["come from the character's effort", "happen by luck", "be done by someone else"], 0, "Characters should solve their own problems."),
        _q("How many stages go in the story map?", ["Four", "Two", "Eight"], 0, "One box per stage."),
